from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product
import heapq
from collections import Counter


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    choices = []
    for name in names:
        allowed = [v for v in rows[name]
                   if v not in blocked.get(name, [])
                   and (name not in pins or pins[name] == v)]
        choices.append([-1] + sorted(allowed))

    order = names if name_order == "ascending" else list(reversed(names))
    best_vector = None
    best = None
    roots = data["roots"]

    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name, -1) < 0 or
               not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        graph = {name: [] for name, version in selected.items() if version >= 0}
        valid = True
        for name, version in selected.items():
            if version < 0:
                continue
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = selected.get(target, -1)
                if target_version < dep["min"] or target_version > dep["max"]:
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be precisely the roots' dependency closure.
        reached = set()
        stack = list(roots)
        while stack:
            node = stack.pop()
            if node in reached:
                continue
            reached.add(node)
            stack.extend(graph.get(node, []))
        if reached != set(graph):
            continue

        done, active = set(), set()
        def visit(node):
            if node in active:
                return False
            if node in done:
                return True
            active.add(node)
            if any(not visit(child) for child in graph[node]):
                return False
            active.remove(node)
            done.add(node)
            return True
        if not all(visit(node) for node in graph):
            continue

        vector = tuple(selected[name] for name in order)
        if best_vector is None or (vector > best_vector if preference == "maximum"
                                   else vector < best_vector):
            best_vector = vector
            best = {name: version for name, version in selected.items() if version >= 0}

    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _dependency_builder(preference, name_order):
    return lambda data: dependency_solver(data, preference, name_order)


def component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        eid = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if eid not in winners or key > winners[eid][0]:
            winners[eid] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(n, d=10000):
        return (n + d // 2) // d if half_up else n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def component_07(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    candidates = [j for j in jobs if j["id"] not in blocked]
    best_ids = None
    best_value = None

    for subset in __import__("itertools").combinations(candidates, k):
        ids = {j["id"] for j in subset}
        if not mandatory <= ids:
            continue
        counts = Counter(j["group"] for j in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        ends = []
        valid = True
        for job in ordered:
            ends = [end for end in ends if end > job["start"]]
            ends.append(job["end"])
            if len(ends) > 2:
                valid = False
                break
        if not valid:
            continue
        selected = tuple(sorted(ids))
        value = sum(j["value"] for j in subset)
        if best_value is None or value > best_value or (value == best_value and selected > best_ids):
            best_value, best_ids = value, selected

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = bit.get(start, 0)
    initial = (start, initial_mask, data["coupons"])
    dist = {initial: data["start"]}
    queue = [(data["start"], start, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                new_mask = mask | bit.get(nxt, 0)
                new_state = (nxt, new_mask, left)
                if arrival < dist.get(new_state, float("inf")):
                    dist[new_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, new_mask, left))
    return {"arrival": None}


SOLVERS = {
    "component_01": _dependency_builder("maximum", "descending"),
    "component_02": _dependency_builder("minimum", "descending"),
    "component_03": _dependency_builder("maximum", "ascending"),
    "component_04": _dependency_builder("minimum", "ascending"),
    "component_05": _dependency_builder("maximum", "descending"),
    "component_06": component_06,
    "component_07": component_07,
    "component_08": component_08,
}
